-- Área de aterrizaje del archivo exportado por el punto de venta.
-- Todo llega como texto: la validación decide qué es válido, no el BULK INSERT.
-- Formato supuesto de la exportación (una fila por línea de factura); se confirma
-- contra una exportación real en la historia US-10.
CREATE TABLE [stg].[VentaLinea]
(
    [idLinea]         INT IDENTITY(1,1) NOT NULL,
    [numeroFactura]   NVARCHAR(60)  NULL,
    [fechaHora]       NVARCHAR(40)  NULL,
    [telefonoCliente] NVARCHAR(40)  NULL,
    [nombreCliente]   NVARCHAR(200) NULL,
    [usuarioAsesor]   NVARCHAR(100) NULL,
    [referencia]      NVARCHAR(80)  NULL,
    [cantidad]        NVARCHAR(40)  NULL,
    [precioUnitario]  NVARCHAR(40)  NULL,
    [descuento]       NVARCHAR(40)  NULL,
    [anulada]         NVARCHAR(10)  NULL,
    [esGarantia]      NVARCHAR(10)  NULL,
    [idCarga]         INT           NULL,
    [estado]          VARCHAR(10)   NULL,  -- VALIDA, RECHAZADA u OMITIDA
    [motivo]          VARCHAR(200)  NULL,
    CONSTRAINT [PK_VentaLinea] PRIMARY KEY CLUSTERED ([idLinea])
);
GO
-- Vista sobre la que se hace el BULK INSERT: expone solo las 11 columnas del
-- archivo, de modo que no se necesita archivo de formato.
CREATE VIEW [stg].[vw_VentaLineaCarga]
AS
SELECT [numeroFactura], [fechaHora], [telefonoCliente], [nombreCliente], [usuarioAsesor],
       [referencia], [cantidad], [precioUnitario], [descuento], [anulada], [esGarantia]
FROM [stg].[VentaLinea];
GO
-- Carga el archivo CSV exportado por el punto de venta en stg.VentaLinea.
-- La cuenta que ejecuta este procedimiento necesita el permiso de servidor
-- ADMINISTER BULK OPERATIONS (rol bulkadmin) y lectura sobre la carpeta de entrada.
CREATE PROCEDURE [etl].[usp_CargarArchivoStaging]
    @ruta    NVARCHAR(260),
    @idCarga INT
AS
BEGIN
    SET NOCOUNT ON;
    -- La ruta se arma en SQL dinámico: se rechaza cualquier carácter que permita inyección
    IF @ruta IS NULL OR @ruta LIKE N'%''%' OR @ruta LIKE N'%;%' OR @ruta LIKE N'%--%'
        THROW 50010, N'Ruta de archivo no válida.', 1;

    DELETE FROM [stg].[VentaLinea];

    DECLARE @sql NVARCHAR(MAX) =
        N'BULK INSERT [stg].[vw_VentaLineaCarga] FROM N''' + @ruta + N''' ' +
        N'WITH (FORMAT = ''CSV'', FIRSTROW = 2, FIELDTERMINATOR = '','', ' +
        N'ROWTERMINATOR = ''0x0a'', CODEPAGE = ''65001'', TABLOCK);';
    EXEC sys.sp_executesql @sql;

    -- Los archivos generados en Windows terminan las líneas con CR+LF
    UPDATE [stg].[VentaLinea]
    SET [idCarga]    = @idCarga,
        [esGarantia] = REPLACE([esGarantia], NCHAR(13), N'');

    UPDATE [dbo].[CargaDatos]
    SET [registrosProcesados] = (SELECT COUNT(*) FROM [stg].[VentaLinea])
    WHERE [idCarga] = @idCarga;
END;
GO
-- Lleva las líneas válidas de staging al modelo dimensional en una sola transacción.
-- El costo se congela al momento de la carga para que el margen histórico no cambie.
CREATE PROCEDURE [etl].[usp_CargarVentasDW]
    @idCarga INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        -- Líneas válidas ya tipadas
        SELECT LTRIM(RTRIM(s.[numeroFactura]))                              AS numeroFactura,
               TRY_CONVERT(DATETIME2(0), s.[fechaHora], 120)                AS fechaHora,
               NULLIF(LTRIM(RTRIM(s.[telefonoCliente])), N'')               AS telefono,
               NULLIF(LTRIM(RTRIM(s.[nombreCliente])), N'')                 AS nombre,
               u.[idUsuario],
               p.[idProducto],
               p.[costoAdquisicion],
               TRY_CONVERT(INT, s.[cantidad])                               AS cantidad,
               TRY_CONVERT(DECIMAL(10,2), s.[precioUnitario])               AS precioUnitario,
               TRY_CONVERT(DECIMAL(10,2), ISNULL(NULLIF(s.[descuento], N''), N'0')) AS descuento,
               CONVERT(BIT, s.[anulada])                                    AS anulada,
               CONVERT(BIT, s.[esGarantia])                                 AS esGarantia
        INTO #lineas
        FROM [stg].[VentaLinea] s
        JOIN [dbo].[Producto] p ON p.[referencia] = LTRIM(RTRIM(s.[referencia]))
        JOIN [dbo].[Usuario]  u ON u.[nombreUsuario] = LTRIM(RTRIM(s.[usuarioAsesor]))
        WHERE s.[idCarga] = @idCarga AND s.[estado] = 'VALIDA';

        -- 1. Clientes nuevos, identificados por teléfono (RN-07). Sin teléfono = consumidor final.
        SELECT CONVERT(VARCHAR(120), ISNULL(MAX(l.nombre), N'Cliente sin nombre')), CONVERT(VARCHAR(15), l.telefono)
        FROM #lineas l
        WHERE l.telefono IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM [dbo].[Cliente] c WHERE c.[telefono] = l.telefono)
        GROUP BY l.telefono;

        -- 2. Encabezados de venta (RN-08: la fecha es la de facturación)
        SELECT l.numeroFactura, c.[idCliente], MAX(l.idUsuario),
               CONVERT(INT, CONVERT(CHAR(8), MAX(l.fechaHora), 112)), MAX(l.fechaHora),
               SUM(l.cantidad * l.precioUnitario - l.descuento),
               CONVERT(BIT, MAX(CONVERT(INT, l.anulada)))
        FROM #lineas l
        LEFT JOIN [dbo].[Cliente] c ON c.[telefono] = l.telefono
        GROUP BY l.numeroFactura, c.[idCliente];

        -- 3. Detalle (grano del hecho). El par de lentes llega como una sola línea (RN-06).
        SELECT v.[idVenta], l.idProducto, l.cantidad, l.precioUnitario, l.costoAdquisicion, l.descuento, l.esGarantia
        FROM #lineas l
        JOIN [dbo].[Venta] v ON v.[numeroFactura] = l.numeroFactura;

        DECLARE @incorporadas INT = @@ROWCOUNT;

        UPDATE [dbo].[CargaDatos]
        SET [registrosIncorporados] = @incorporadas,
            [resultado] = CASE WHEN [registrosRechazados] > 0 THEN 'PARCIAL' ELSE 'EXITOSA' END
        WHERE [idCarga] = @idCarga;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        UPDATE [dbo].[CargaDatos] SET [resultado] = 'FALLIDA' WHERE [idCarga] = @idCarga;
        THROW;
    END CATCH;
END;
GO
-- Punto de entrada de la carga de ventas. Es lo que invoca el paquete SSIS
-- CargaVentas.dtsx (tarea Ejecutar SQL) y lo que usan las pruebas automatizadas.
CREATE PROCEDURE [etl].[usp_EjecutarCargaVentas]
    @ruta      NVARCHAR(260),
    @tipoCarga VARCHAR(20) = 'INCREMENTAL',
    @idCarga   INT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    EXEC [etl].[usp_IniciarCarga] @tipoCarga = @tipoCarga, @idCarga = @idCarga OUTPUT;
    BEGIN TRY
        EXEC [etl].[usp_CargarArchivoStaging] @ruta = @ruta, @idCarga = @idCarga;
        EXEC [etl].[usp_ValidarVentas] @idCarga = @idCarga;
        EXEC [etl].[usp_CargarVentasDW] @idCarga = @idCarga;
    END TRY
    BEGIN CATCH
        UPDATE [dbo].[CargaDatos] SET [resultado] = 'FALLIDA' WHERE [idCarga] = @idCarga;
        THROW;
    END CATCH;
    SELECT [idCarga], [resultado], [registrosProcesados], [registrosIncorporados], [registrosRechazados]
    FROM [dbo].[CargaDatos] WHERE [idCarga] = @idCarga;
END;
GO
-- Registra el inicio de una carga. Nace como FALLIDA a propósito: si el proceso
-- se interrumpe, la bitácora nunca muestra como exitosa una carga que no terminó.
CREATE PROCEDURE [etl].[usp_IniciarCarga]
    @tipoCarga VARCHAR(20) = 'INCREMENTAL',
    @idCarga   INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    VALUES (@tipoCarga, 'FALLIDA');
    SET @idCarga = CONVERT(INT, SCOPE_IDENTITY());
END;
GO
-- Llena DimTiempo entre dos fechas. Solo agrega las fechas que faltan (idempotente).
CREATE PROCEDURE [etl].[usp_PoblarDimTiempo]
    @desde DATE,
    @hasta DATE
AS
BEGIN
    SET NOCOUNT ON;
    SET LANGUAGE Spanish;
    WITH n AS (
        SELECT TOP (DATEDIFF(DAY, @desde, @hasta) + 1)
               ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 AS d
        FROM sys.all_objects a CROSS JOIN sys.all_objects b
    ), f AS (
        SELECT DATEADD(DAY, d, @desde) AS fecha FROM n
    )
    SELECT CONVERT(INT, CONVERT(CHAR(8), f.fecha, 112)),
           f.fecha,
           YEAR(f.fecha),
           DATEPART(QUARTER, f.fecha),
           MONTH(f.fecha),
           DATENAME(MONTH, f.fecha),
           DATENAME(WEEKDAY, f.fecha),
           CASE WHEN DATEDIFF(DAY, '19000101', f.fecha) % 7 IN (5, 6) THEN 1 ELSE 0 END
    FROM f
    WHERE NOT EXISTS (SELECT 1 FROM [dbo].[DimTiempo] t WHERE t.[fecha] = f.fecha);
END;
GO
-- Valida las líneas de staging. Las inválidas se apartan en RegistroRechazado con
-- su motivo (RF-03); las facturas ya cargadas se omiten sin contarse como error.
-- Si el porcentaje de rechazo supera el umbral (parámetro UMB-RECH), la carga se detiene.
CREATE PROCEDURE [etl].[usp_ValidarVentas]
    @idCarga       INT,
    @umbralRechazo DECIMAL(5,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @umbralRechazo IS NULL
        SELECT @umbralRechazo = ISNULL(TRY_CONVERT(DECIMAL(5,2), [valor]), 5)
        FROM [dbo].[ParametroRegla] WHERE [codigoRegla] = 'UMB-RECH';
    SET @umbralRechazo = ISNULL(@umbralRechazo, 5);

    UPDATE [stg].[VentaLinea] SET [estado] = NULL, [motivo] = NULL WHERE [idCarga] = @idCarga;

    -- 1. Facturas que ya existen en el data warehouse: se omiten (carga idempotente)
    UPDATE s SET [estado] = 'OMITIDA'
    FROM [stg].[VentaLinea] s
    WHERE s.[idCarga] = @idCarga
      AND EXISTS (SELECT 1 FROM [dbo].[Venta] v WHERE v.[numeroFactura] = LTRIM(RTRIM(s.[numeroFactura])));

    -- 2. Reglas de calidad por línea (la primera que falla define el motivo)
    UPDATE s SET [estado] = 'RECHAZADA', [motivo] = x.[motivo]
    FROM [stg].[VentaLinea] s
    LEFT JOIN [dbo].[Producto]  p ON p.[referencia]    = LTRIM(RTRIM(s.[referencia])) AND p.[activo] = 1
    LEFT JOIN [dbo].[Usuario]   u ON u.[nombreUsuario] = LTRIM(RTRIM(s.[usuarioAsesor])) AND u.[activo] = 1
    LEFT JOIN [dbo].[DimTiempo] t ON t.[fecha] = TRY_CONVERT(DATE, TRY_CONVERT(DATETIME2(0), s.[fechaHora], 120))
    CROSS APPLY (SELECT CASE
        WHEN NULLIF(LTRIM(RTRIM(s.[numeroFactura])), N'') IS NULL                         THEN 'Número de factura vacío'
        WHEN TRY_CONVERT(DATETIME2(0), s.[fechaHora], 120) IS NULL                          THEN 'Fecha y hora con formato inválido'
        WHEN t.[idFecha] IS NULL                                                            THEN 'Fecha fuera del calendario'
        WHEN TRY_CONVERT(INT, s.[cantidad]) IS NULL OR TRY_CONVERT(INT, s.[cantidad]) <= 0  THEN 'Cantidad inválida'
        WHEN TRY_CONVERT(DECIMAL(10,2), s.[precioUnitario]) IS NULL
          OR TRY_CONVERT(DECIMAL(10,2), s.[precioUnitario]) < 0                             THEN 'Precio unitario inválido'
        WHEN TRY_CONVERT(DECIMAL(10,2), ISNULL(NULLIF(s.[descuento], N''), N'0')) IS NULL
          OR TRY_CONVERT(DECIMAL(10,2), ISNULL(NULLIF(s.[descuento], N''), N'0')) < 0       THEN 'Descuento inválido'
        WHEN TRY_CONVERT(DECIMAL(10,2), ISNULL(NULLIF(s.[descuento], N''), N'0'))
           > TRY_CONVERT(INT, s.[cantidad]) * TRY_CONVERT(DECIMAL(10,2), s.[precioUnitario]) THEN 'Descuento mayor que el importe de la línea'
        WHEN p.[idProducto] IS NULL                                                         THEN LEFT('Producto inexistente: ' + ISNULL(CONVERT(VARCHAR(80), s.[referencia]), '(vacío)'), 200)
        WHEN u.[idUsuario] IS NULL                                                          THEN LEFT('Asesor inexistente: ' + ISNULL(CONVERT(VARCHAR(100), s.[usuarioAsesor]), '(vacío)'), 200)
        WHEN ISNULL(s.[anulada], N'') NOT IN (N'0', N'1')
          OR ISNULL(s.[esGarantia], N'') NOT IN (N'0', N'1')                               THEN 'Indicador de anulada o garantía inválido'
        END AS [motivo]) x
    WHERE s.[idCarga] = @idCarga AND s.[estado] IS NULL AND x.[motivo] IS NOT NULL;

    -- 3. Una factura con encabezado inconsistente entre sus líneas se rechaza completa
    UPDATE s SET [estado] = 'RECHAZADA', [motivo] = 'Factura con encabezado inconsistente entre líneas'
    FROM [stg].[VentaLinea] s
    WHERE s.[idCarga] = @idCarga AND ISNULL(s.[estado], '') <> 'OMITIDA'
      AND s.[numeroFactura] IN (
          SELECT [numeroFactura] FROM [stg].[VentaLinea]
          WHERE [idCarga] = @idCarga AND ISNULL([estado], '') <> 'OMITIDA'
          GROUP BY [numeroFactura]
          HAVING COUNT(DISTINCT ISNULL([fechaHora], N'')) > 1
              OR COUNT(DISTINCT ISNULL([telefonoCliente], N'')) > 1
              OR COUNT(DISTINCT ISNULL([usuarioAsesor], N'')) > 1
              OR COUNT(DISTINCT ISNULL([anulada], N'')) > 1);

    UPDATE [stg].[VentaLinea] SET [estado] = 'VALIDA' WHERE [idCarga] = @idCarga AND [estado] IS NULL;

    SELECT @idCarga,
           CONCAT_WS(N',', [numeroFactura], [fechaHora], [telefonoCliente], [nombreCliente], [usuarioAsesor],
                     [referencia], [cantidad], [precioUnitario], [descuento], [anulada], [esGarantia]),
           [motivo]
    FROM [stg].[VentaLinea]
    WHERE [idCarga] = @idCarga AND [estado] = 'RECHAZADA';

    DECLARE @evaluadas INT, @rechazadas INT, @porcentaje DECIMAL(5,2);
    SELECT @evaluadas  = SUM(CASE WHEN [estado] <> 'OMITIDA' THEN 1 ELSE 0 END),
           @rechazadas = SUM(CASE WHEN [estado] = 'RECHAZADA' THEN 1 ELSE 0 END)
    FROM [stg].[VentaLinea] WHERE [idCarga] = @idCarga;

    SET @evaluadas  = ISNULL(@evaluadas, 0);
    SET @rechazadas = ISNULL(@rechazadas, 0);
    SET @porcentaje = CASE WHEN @evaluadas = 0 THEN 0 ELSE 100.0 * @rechazadas / @evaluadas END;

    UPDATE [dbo].[CargaDatos] SET [registrosRechazados] = @rechazadas WHERE [idCarga] = @idCarga;

    IF @porcentaje > @umbralRechazo
    BEGIN
        DECLARE @mensaje NVARCHAR(400) = CONCAT(N'El rechazo de ', @porcentaje, N' % supera el umbral de ',
                                                @umbralRechazo, N' %. La carga se detuvo sin modificar el data warehouse.');
        THROW 50020, @mensaje, 1;
    END;
END;
GO
-- Tabla de fechas para Power BI (comparativos contra el mes y el año anterior, RF-16).
CREATE VIEW [rpt].[vw_Calendario]
AS
SELECT [fecha], [anio], [trimestre], [mes], [nombreMes], [diaSemana], [esFinDeSemana]
FROM [dbo].[DimTiempo];
GO
-- Resultado de las campañas de renovación (RF-12): a quién se contactó, qué respondió
-- y cuánto vendió la campaña. Una fila por cliente incluido en cada campaña.
CREATE VIEW [rpt].[vw_CampaniasResultado]
AS
SELECT ca.[idCampania],
       ca.[nombre]            AS [campania],
       ca.[fechaGeneracion],
       dc.[idCliente],
       dc.[fechaContacto],
       ISNULL(dc.[resultado], 'SIN CONTACTO') AS [resultado],
       CONVERT(BIT, CASE WHEN dc.[resultado] = 'COMPRA' THEN 1 ELSE 0 END) AS [convirtio],
       v.[numeroFactura]      AS [facturaGenerada],
       CONVERT(DECIMAL(12,2), ISNULL(CASE WHEN v.[anulada] = 0 THEN v.[total] END, 0)) AS [ventaGenerada]
FROM [dbo].[Campania] ca
JOIN [dbo].[DetalleCampania] dc ON dc.[idCampania] = ca.[idCampania]
LEFT JOIN [dbo].[Venta] v ON v.[idVenta] = dc.[idVentaGenerada];
GO
-- Una fila por ejecución de la carga nocturna, con su porcentaje de rechazo.
-- Sirve para la página de calidad de datos del tablero.
CREATE VIEW [rpt].[vw_CargasResumen]
AS
SELECT cd.[idCarga],
       cd.[fechaEjecucion],
       CONVERT(DATE, cd.[fechaEjecucion]) AS [fecha],
       cd.[tipoCarga],
       cd.[resultado],
       cd.[registrosProcesados],
       cd.[registrosIncorporados],
       cd.[registrosRechazados],
       CONVERT(DECIMAL(5,2), CASE WHEN cd.[registrosProcesados] = 0 THEN 0
            ELSE 100.0 * cd.[registrosRechazados] / cd.[registrosProcesados] END) AS [porcentajeRechazo]
FROM [dbo].[CargaDatos] cd;
GO
-- Clientes y su ciclo de renovación (RN-01), con la condición de contacto (RN-09).
-- El ciclo se lee de ParametroRegla: cambiarlo no requiere modificar esta vista.
CREATE VIEW [rpt].[vw_ClientesRenovacion]
AS
SELECT c.[idCliente],
       c.[nombreCompleto],
       c.[telefono],
       ult.[ultimaCompra],
       m.[mesesDesdeCompra],
       par.[meses]                                                         AS [cicloMeses],
       CONVERT(BIT, CASE WHEN m.[mesesDesdeCompra] >= par.[meses] THEN 1 ELSE 0 END) AS [cicloVencido],
       CONVERT(BIT, CASE WHEN c.[telefono] IS NOT NULL
                          AND c.[consentimientoContacto] = 1
                          AND c.[fechaExclusion] IS NULL THEN 1 ELSE 0 END) AS [contactable],
       CASE WHEN c.[telefono] IS NULL             THEN 'SIN TELEFONO'
            WHEN c.[consentimientoContacto] = 0   THEN 'SIN CONSENTIMIENTO'
            WHEN c.[fechaExclusion] IS NOT NULL   THEN 'EXCLUSION SOLICITADA'
       END                                                                 AS [motivoExclusion]
FROM [dbo].[Cliente] c
JOIN (SELECT v.[idCliente], MAX(v.[fechaHora]) AS [ultimaCompra]
      FROM [dbo].[Venta] v
      WHERE v.[anulada] = 0 AND v.[idCliente] IS NOT NULL
      GROUP BY v.[idCliente]) ult ON ult.[idCliente] = c.[idCliente]
CROSS APPLY (SELECT DATEDIFF(MONTH, ult.[ultimaCompra], GETDATE())
                    - CASE WHEN DAY(GETDATE()) < DAY(ult.[ultimaCompra]) THEN 1 ELSE 0 END AS [mesesDesdeCompra]) m
CROSS APPLY (SELECT ISNULL((SELECT TRY_CONVERT(INT, r.[valor]) FROM [dbo].[ParametroRegla] r
                            WHERE r.[codigoRegla] = 'RN-01'), 18) AS [meses]) par
WHERE c.[activo] = 1;
GO
-- Total facturado por mes, para compararlo contra el reporte del punto de venta (US-16).
CREATE VIEW [rpt].[vw_ConciliacionMensual]
AS
SELECT t.[anio],
       t.[mes],
       COUNT(*)                        AS [facturas],
       CONVERT(DECIMAL(14,2), SUM(v.[total])) AS [totalFacturado]
FROM [dbo].[Venta] v
JOIN [dbo].[DimTiempo] t ON t.[idFecha] = v.[idFecha]
WHERE v.[anulada] = 0
GROUP BY t.[anio], t.[mes];
GO
-- Alertas de inventario: bajo el mínimo (RN-03) y sin movimiento (RN-04).
-- Los días sin movimiento se leen de ParametroRegla; si falta el parámetro se usan 180.
CREATE VIEW [rpt].[vw_InventarioAlertas]
AS
SELECT p.[idProducto],
       p.[referencia],
       p.[descripcion],
       i.[existenciaActual],
       p.[nivelMinimo],
       i.[fechaUltimoMovimiento],
       i.[costoPromedio],
       CONVERT(BIT, CASE WHEN i.[existenciaActual] < p.[nivelMinimo] THEN 1 ELSE 0 END) AS [bajoMinimo],
       CONVERT(BIT, CASE WHEN i.[fechaUltimoMovimiento] IS NULL
                          OR DATEDIFF(DAY, i.[fechaUltimoMovimiento], CONVERT(DATE, GETDATE())) >= par.[dias]
                         THEN 1 ELSE 0 END)                                             AS [sinMovimiento],
       CONVERT(DECIMAL(12,2), i.[existenciaActual] * i.[costoPromedio])                 AS [valorEnBodega]
FROM [dbo].[Producto] p
JOIN [dbo].[Inventario] i ON i.[idProducto] = p.[idProducto]
CROSS APPLY (SELECT ISNULL((SELECT TRY_CONVERT(INT, r.[valor]) FROM [dbo].[ParametroRegla] r
                            WHERE r.[codigoRegla] = 'RN-04'), 180) AS [dias]) par
WHERE p.[activo] = 1;
GO
-- Rechazos de cada carga con su motivo, para la revisión de la administración.
CREATE VIEW [rpt].[vw_RechazosPorCarga]
AS
SELECT cd.[idCarga],
       cd.[fechaEjecucion],
       cd.[resultado],
       r.[idRechazo],
       r.[motivoRechazo],
       r.[contenidoOriginal],
       r.[corregido]
FROM [dbo].[CargaDatos] cd
JOIN [dbo].[RegistroRechazado] r ON r.[idCarga] = cd.[idCarga];
GO
-- Hecho de ventas listo para Power BI. Excluye ventas anuladas y reposiciones en
-- garantía, que no son ingreso (RN-10). Margen según RN-05 con el costo congelado.
CREATE VIEW [rpt].[vw_VentasDetalle]
AS
SELECT d.[idDetalle],
       v.[idVenta],
       v.[numeroFactura],
       v.[fechaHora],
       t.[fecha],
       t.[anio],
       t.[trimestre],
       t.[mes],
       t.[nombreMes],
       v.[idCliente],
       ISNULL(c.[nombreCompleto], 'Consumidor final')                          AS [cliente],
       u.[nombreCompleto]                                                     AS [asesor],
       p.[referencia],
       p.[descripcion]                                                        AS [producto],
       cat.[nombre]                                                           AS [categoria],
       ISNULL(pr.[nombre], 'Sin proveedor')                                   AS [proveedor],
       d.[cantidad],
       d.[precioUnitario],
       d.[descuento],
       CONVERT(DECIMAL(12,2), d.[cantidad] * d.[precioUnitario] - d.[descuento])                        AS [ingreso],
       CONVERT(DECIMAL(12,2), d.[cantidad] * d.[costoUnitario])                                         AS [costo],
       CONVERT(DECIMAL(12,2), d.[cantidad] * d.[precioUnitario] - d.[descuento] - d.[cantidad] * d.[costoUnitario]) AS [margen]
FROM [dbo].[DetalleVenta] d
JOIN [dbo].[Venta]       v   ON v.[idVenta]      = d.[idVenta]
JOIN [dbo].[DimTiempo]   t   ON t.[idFecha]      = v.[idFecha]
JOIN [dbo].[Usuario]     u   ON u.[idUsuario]    = v.[idUsuario]
JOIN [dbo].[Producto]    p   ON p.[idProducto]   = d.[idProducto]
JOIN [dbo].[Categoria]   cat ON cat.[idCategoria] = p.[idCategoria]
LEFT JOIN [dbo].[Proveedor] pr ON pr.[idProveedor] = p.[idProveedor]
LEFT JOIN [dbo].[Cliente]   c  ON c.[idCliente]    = v.[idCliente]
WHERE v.[anulada] = 0
  AND d.[esGarantia] = 0;
GO
